#include "viewer/imported_world_session.hpp"
#include <algorithm>
#include <cmath>
namespace pvr::viewer {
bool ImportedWorldSession::load(const std::filesystem::path& path){auto read=minecraft::MinecraftWorldReader::read(path);diagnostic_.clear();if(!read.ok()){if(!read.diagnostics.empty())diagnostic_=read.diagnostics.front().message;loaded_=false;return false;}data_=std::move(read.data);world_=WorldTruth(data_.metadata.seed,data_.metadata.sectionSize);auto imported=minecraft::MinecraftWorldAdapter::import(data_,world_,{});if(!imported.ok){diagnostic_="World Truth import failed";loaded_=false;return false;}importedBlocks_=imported.report.importedBlocks;worldTruthVersion_=0;for(const auto&c:data_.chunks)for(const auto&s:c.sections)worldTruthVersion_+=world_.chunkVersion({c.x,s.y,c.z});rendererInit_=runtime_.initialize();rebuildCandidates();loaded_=true;return true;}
void ImportedWorldSession::rebuildCandidates(){candidates_.clear();std::uint64_t id=1;for(const auto&c:data_.chunks){float x=float(c.x*16+8),z=float(c.z*16+8);candidates_.push_back({id,{x,0,z},11.3f,1.0f,float(1.0f/(1.0f+std::sqrt(x*x+z*z))),std::uint32_t(id)});++id;}}
ImportedRenderMetrics ImportedWorldSession::render(const ViewFrustum& view,std::size_t maxDraws){ImportedRenderMetrics m;m.mode=mode_;m.importedChunks=importedChunkCount();m.importedBlocks=importedBlocks_;m.worldTruthVersion=worldTruthVersion_;m.backend=rendererInit_.message;if(!loaded_){m.diagnostic=diagnostic_;return m;}if(mode_==RenderComparisonMode::Perceptual){for(const auto&c:candidates_)runtime_.add_candidate(c);auto r=runtime_.render(view,maxDraws);m.visible=r.visible_count;m.rejected=r.rejected;m.drawCount=r.draw_count;}else{const float maxDistance=64.0f;for(const auto&c:candidates_){float dx=c.position.x-view.position.x,dz=c.position.z-view.position.z;if(std::sqrt(dx*dx+dz*dz)<=maxDistance)++m.visible;}m.rejected=candidates_.size()-m.visible;m.drawCount=std::min(m.visible,maxDraws);}return m;}
}
